-- Q21: Comprehensive weighted performance ranking system
SELECT p.full_name, pcs.format, ROUND(((pcs.runs_scored * 0.01) + (pcs.batting_average * 0.5) + (pcs.strike_rate * 0.3)), 2) AS batting_pts, ROUND(((pcs.wickets_taken * 2) + ((50 - pcs.bowling_average) * 0.5) + ((6 - pcs.economy_rate) * 2)), 2) AS bowling_pts, ROUND(((pcs.catches * 3) + (pcs.stumpings * 5)), 2) AS fielding_pts, ROUND(((pcs.runs_scored * 0.01) + (pcs.batting_average * 0.5) + (pcs.strike_rate * 0.3)) + ((pcs.wickets_taken * 2) + ((50 - pcs.bowling_average) * 0.5) + ((6 - pcs.economy_rate) * 2)) + ((pcs.catches * 3) + (pcs.stumpings * 5)), 2) AS total_ranking_score FROM player_career_stats pcs JOIN players p ON pcs.player_id = p.player_id ORDER BY total_ranking_score DESC;